export const FloatingStyles = (args) => {
  const tooltipLabel = 'Options';
  return (
    <div
      style={{
        width: '100%',
        display: 'flex',
        justifyContent: 'center',
      }}>
      <Tooltip label={tooltipLabel} align={args.align}>
        <button className="sb-tooltip-trigger" type="button">
          <OverflowMenuVertical />
        </button>
      </Tooltip>
    </div>
  );
};

FloatingStyles.args = {
  align: 'bottom',
};

FloatingStyles.argTypes = {
  align: {
    options: [
      'top',
      'top-start',
      'top-end',

      'bottom',
      'bottom-start',
      'bottom-end',

      'left',
      'left-end',
      'left-start',

      'right',
      'right-end',
      'right-start',
    ],
    control: {
      type: 'select',
    },
  },
  label: {
    control: {
